//! Quality tiers: one set of assets and render settings per device class.
//!
//! * Low  - ~6k triangles, 512 px textures without normal maps, no shadows, no outline, no MSAA.
//! * Mid  - ~12k triangles, 1024 px textures, a 1024 px shadow map, 4x MSAA.
//! * High - full meshes, 2048 px textures, a 2048 px shadow map, 4x MSAA.
//!
//! Meshes come from `characters/lod1` (Mid) and `characters/lod2` (Low), generated by
//! `tools/make_lods.py`; High uses the originals. Textures come from `textures_basis/<size>`.

use bevy::{light::DirectionalLightShadowMap, prelude::*, render::view::Msaa};

#[derive(Resource, Clone, Copy, PartialEq, Eq, Debug)]
pub enum Quality {
    Low,
    Mid,
    High,
}

impl Quality {
    /// Phones start on Mid (change it from your own device detection); desktop on High.
    /// `TOON_AVATAR_QUALITY=low|mid|high` overrides it, which is handy for desktop testing.
    pub fn default_for_device() -> Self {
        if let Ok(value) = std::env::var("TOON_AVATAR_QUALITY") {
            match value.as_str() {
                "low" => return Quality::Low,
                "mid" => return Quality::Mid,
                "high" => return Quality::High,
                _ => {}
            }
        }
        if cfg!(any(target_os = "ios", target_os = "android")) {
            Quality::Mid
        } else {
            Quality::High
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Quality::Low => "Low",
            Quality::Mid => "Mid",
            Quality::High => "High",
        }
    }

    pub fn next(self) -> Self {
        match self {
            Quality::Low => Quality::Mid,
            Quality::Mid => Quality::High,
            Quality::High => Quality::Low,
        }
    }

    /// `characters/models/X.glb` -> `characters/lod2/models/X.glb` for the reduced tiers.
    pub fn model_path(self, glb: &str) -> String {
        let lod = match self {
            Quality::Low => "lod2",
            Quality::Mid => "lod1",
            Quality::High => return glb.to_string(),
        };
        match glb.strip_prefix("characters/") {
            Some(rest) => format!("characters/{lod}/{rest}"),
            None => glb.to_string(),
        }
    }

    /// Size folder of the compressed textures.
    pub fn texture_size(self) -> u32 {
        match self {
            Quality::Low => 512,
            Quality::Mid => 1024,
            Quality::High => 2048,
        }
    }

    pub fn normal_maps(self) -> bool {
        self != Quality::Low
    }

    pub fn outline(self) -> bool {
        self != Quality::Low
    }

    pub(crate) fn shadow_map_size(self) -> Option<usize> {
        match self {
            Quality::Low => None,
            Quality::Mid => Some(1024),
            Quality::High => Some(2048),
        }
    }

    /// WebGPU only guarantees 1 and 4 samples, so 2x/8x are avoided (2x crashed the iOS simulator).
    pub(crate) fn msaa(self) -> Msaa {
        match self {
            Quality::Low => Msaa::Off,
            Quality::Mid => Msaa::Sample4,
            Quality::High => Msaa::Sample4,
        }
    }
}

/// Inserts the [`Quality`] resource (the device default unless the app already did).
pub struct QualityPlugin;

impl Plugin for QualityPlugin {
    fn build(&self, app: &mut App) {
        if !app.world().contains_resource::<Quality>() {
            app.insert_resource(Quality::default_for_device());
        }
    }
}

/// Opt-in: applies the render settings of the current tier (shadow map size, MSAA) to the
/// scene's lights and cameras. A game with its own camera settings should not add this.
pub struct QualityRenderSettingsPlugin;

impl Plugin for QualityRenderSettingsPlugin {
    fn build(&self, app: &mut App) {
        app.insert_resource(DirectionalLightShadowMap { size: 2048 })
            .add_systems(Update, apply_quality);
    }
}

fn apply_quality(
    quality: Res<Quality>,
    mut shadow_map: ResMut<DirectionalLightShadowMap>,
    mut lights: Query<&mut DirectionalLight>,
    mut cameras: Query<&mut Msaa>,
) {
    if !quality.is_changed() {
        return;
    }
    let size = quality.shadow_map_size();
    if let Some(size) = size {
        shadow_map.size = size;
    }
    for mut light in &mut lights {
        light.shadow_maps_enabled = size.is_some();
    }
    for mut msaa in &mut cameras {
        *msaa = quality.msaa();
    }
    info!("quality: {}", quality.label());
}
